// === Tab: mySketch ===
const people = 100;

function inRange(angle, init, end){
		return (angle >= init) && (angle < end);
}

class Walker {
	constructor(x, y) {
		this.x = x
		this.y = y 
		this.angle = random(0, TWO_PI);
		this.direction = p5.Vector.fromAngle(this.angle, 2)
		this.vel = random(0.0,0.8);
		this.head = color(random(255),random(255),random(255))
		this.torso = color(random(255),random(255),random(255))
		this.pants = color(random(255),random(255),random(255))
	}

	move(){
		this.x = this.x + this.direction.x * this.vel;
		this.y = this.y + this.direction.y * this.vel;
	}

	updateVel(){
		this.vel = this.vel*0.99;
	}

	changeVel(){
		this.vel = random(0.0,0.8);
	}

	draw() {

			let x = this.x ;
			let y = this.y ;

		push();
			translate(x,y) 

			let s = map(y, 0, height, 0.5, 1);
			scale(s);

			fill(this.head);
			rect(0,0,10);
			fill(this.torso);
			rect(0, 0+16, 10, 20);

			let lrup = this.getLRUP();

			if(lrup == "UP" || lrup == "DOWN"){
				fill(this.pants);
				rect(0-2.6, 0+39, 4.5, 25);
				rect(0+2.6, 0+39, 4.5, 25);
				fill(this.head);
				rect(0-7, 0+14, 2, 15);
				rect(0+7, 0+14, 2, 15);
			}

			if(lrup == "LEFT" || lrup == "RIGHT"){
				fill(this.pants);
				rect(0, 0+39, 10, 25);
				fill(this.head);
				rect(0, 0+14, 2, 15);
			}
		pop();
	}

	isInside() {
		return this.x >= 0 && this.x <= width && this.y >= 0 && this.y <= height
	}

	scare() {
		this.changeDirection();
		this.vel = 2;
	}

	changeDirection(){
		this.angle = random(0, TWO_PI);
		this.direction = p5.Vector.fromAngle(this.angle, 2)
	}

	getLRUP(){
	 // Up: [45, 135]
	 // Right: [0,45] and [315, 360]
	 // Down: [225, 315]
	 // Left: [135, 225]
		let dg = (this.angle * (180 / PI));
		if(inRange(dg, 45, 135)){
				return "UP";
		}
		else if(inRange(dg, 0,45) || inRange(dg, 315, 360)){
				return "RIGHT";
		}
		else if(inRange(dg, 225, 315)){
				return "DOWN";
		}
		else{
			 return "LEFT";
	 }
	}
}

let walkers = []

function setup() {
	rectMode(CENTER);
	createCanvas(windowWidth, windowHeight);
	noStroke();
	for (let i = 0; i < people; i++) {
		walkers.push(new Walker(random(0, width), random(0, height)))
	}
}

function draw() {
	background(250);	
	for(var i = 0; i < people; i++){
		walkers[i].move();
		if(walkers[i].isInside()){
			walkers[i].draw();
		}
		else{
			walkers[i].changeDirection();
		}
	walkers[i].updateVel();
	if(walkers[i].vel < 0.05){
			walkers[i].changeVel();
			walkers[i].changeDirection();
	}
  }  
}

function mousePressed() {
  for(var i = 0; i < people; i++){
		let di = dist(walkers[i].x, walkers[i].y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
		if( di < 50){
			walkers[i].scare();
		}
	}
}

